/**
 * Generate `src/d2kern-113c/mem/layout.generated.ts` from `docs/oracle/route2-layout.json`.
 *
 *   npx tsx tools/oracle/gen-route2-layout.ts          # write
 *   npx tsx tools/oracle/gen-route2-layout.ts --check  # fail if the generated file is stale
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

interface FieldDef {
  readonly name: string
  readonly off: number
  readonly type: 'u8' | 'u16' | 'u32' | 'ptr'
  readonly count?: number
  readonly aliases?: readonly string[]
}
interface StructDef {
  readonly size: number
  readonly allocEvidence?: string
  readonly fields: readonly FieldDef[]
}

const REPO = join(dirname(fileURLToPath(import.meta.url)), '..', '..')
const LAYOUT_PATH = join(REPO, 'docs/oracle/route2-layout.json')
const OUT_PATH = join(REPO, 'src/d2kern-113c/mem/layout.generated.ts')

function generate(): string {
  const layout = JSON.parse(readFileSync(LAYOUT_PATH, 'utf8')) as { structs: Record<string, StructDef> }
  const lines: string[] = [
    '// GENERATED by tools/oracle/gen-route2-layout.ts from docs/oracle/route2-layout.json. Do not edit.',
    '',
    "export type FieldType113c = 'u8' | 'u16' | 'u32' | 'ptr'",
    'export interface FieldLayout113c {',
    '  readonly off: number',
    '  readonly type: FieldType113c',
    '  readonly count: number',
    '}',
    '',
  ]
  for (const [name, def] of Object.entries(layout.structs)) {
    if (def.allocEvidence) {
      lines.push(`/** ${def.allocEvidence} */`)
    }
    lines.push(`export const ${name}_SIZE = ${def.size}`)
    lines.push(`export const ${name} = {`)
    for (const f of def.fields) {
      lines.push(`  ${f.name}: { off: 0x${f.off.toString(16).toUpperCase()}, type: '${f.type}', count: ${f.count ?? 1} },`)
      for (const alias of f.aliases ?? []) {
        lines.push(`  ${alias}: { off: 0x${f.off.toString(16).toUpperCase()}, type: '${f.type}', count: ${f.count ?? 1} },`)
      }
    }
    lines.push('} as const satisfies Record<string, FieldLayout113c>')
    lines.push('')
  }
  return lines.join('\n')
}

const text = generate()
if (process.argv.includes('--check')) {
  const cur = readFileSync(OUT_PATH, 'utf8')
  if (cur !== text) {
    console.error('layout.generated.ts is stale; run npx tsx tools/oracle/gen-route2-layout.ts')
    process.exit(1)
  }
} else {
  writeFileSync(OUT_PATH, text)
  console.log('wrote', OUT_PATH)
}
